target.css:
:root {
  --ink: #182126;
  --paper: #fffdf8;
  --steel: #e8ecea;
  --line: #cbd3d0;
  --muted: #65726f;
  --lime: #d5ef5b;
  --orange: #e66c3a;
}

* {
  box-sizing: border-box;
}

.service-card {
  width: 488px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line);
}

.brand-mark {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  color: var(--ink);
  background: var(--lime);
  border: 1px solid var(--ink);
  border-radius: 50%;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -1px;
}

.title-group {
  min-width: 0;
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.title-group h1 {
  margin: 0;
  font-size: 19px;
  font-weight: 750;
  line-height: 1.05;
  letter-spacing: -0.4px;
}

.status {
  padding: 5px 7px;
  color: var(--ink);
  background: var(--lime);
  border-radius: 5px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.appointment {
  display: grid;
  grid-template-columns: 112px 1fr;
  margin: 13px 16px 10px;
  border: 1px solid var(--ink);
  border-radius: 10px;
  overflow: hidden;
}

.date-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 9px;
  color: var(--paper);
  background: var(--ink);
}

.date-block span,
.date-block small,
.time-block p,
.time-block small {
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.8px;
}

.date-block span {
  color: var(--lime);
}

.date-block strong {
  font-size: 31px;
  line-height: 0.95;
}

.date-block small {
  color: var(--steel);
}

.time-block {
  padding: 12px 14px;
  background: var(--steel);
}

.time-block p {
  margin: 0 0 3px;
  color: var(--muted);
}

.time-block strong {
  display: block;
  font-size: 23px;
  line-height: 1;
  letter-spacing: -0.6px;
}

.time-block strong span {
  color: var(--orange);
  font-size: 12px;
  letter-spacing: 0;
}

.time-block small {
  display: block;
  margin-top: 5px;
  color: var(--muted);
  letter-spacing: 0.2px;
}

.detail-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 0 16px 12px;
}

.detail-list section {
  padding: 8px 10px;
  background: var(--paper);
  border-left: 3px solid var(--orange);
}

.detail-list dt {
  margin-bottom: 3px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.detail-list dd {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.2;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 16px;
  background: var(--steel);
  border-top: 1px solid var(--line);
}

.note {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.action {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--ink);
  border: 1px solid var(--ink);
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

